import{clockText as o}from"./score.min.js";export const BEST_KEY="leaves-best";export function normalizeBests(t){const e={};if(!t||typeof t!="object"||Array.isArray(t))return e;for(const[r,n]of Object.entries(t))/^\d+$/.test(r)&&Number.isFinite(n)&&n>=1&&n<1e5&&(e[r]=Math.round(n));return e}function l(){try{const t=typeof localStorage<"u"?localStorage.getItem(BEST_KEY):null;return normalizeBests(t?JSON.parse(t):null)}catch{return{}}}export function loadBest(t){return l()[String(t)]??null}export function recordBest(t,e){const r=l(),n=String(t),i=r[n]??null,s=Math.max(1,Math.round(e)),u=i===null||s<i;if(u){r[n]=s;try{localStorage.setItem(BEST_KEY,JSON.stringify(r))}catch{}}return{best:u?s:i,previous:i,isNew:u}}export function forgetBest(){try{return localStorage.removeItem(BEST_KEY),!0}catch{return!1}}export function bestWelcomeLine(t){return t?`Your best time to clear the lawn is ${o(t)}. Can you beat it?`:""}export function bestEndLine(t,e){return t?t.previous===null?`Your first clear, in ${o(t.best)}. Now you have a time to beat.`:t.isNew?`A new best time, ${o(t.best)}, down from ${o(t.previous)}.`:`Your best time is still ${o(t.best)}.`:e?`Your best time to clear the lawn is ${o(e)}.`:""}export function bestShareNote(t){return t&&t.isNew&&t.previous!==null?"a new personal best":""}
